update public.content_variants set body = $json${"type":"multiple_choice","answer":"The remainder of the bill bears interest and the debt increases","options":["The remainder of the bill bears interest and the debt increases","The bill was paid immediately","He gets additional rewards","The bank waived the interest"],"question":"What happens if Doni only pays the minimum credit card bill?","difficulty":"beginner","explanation":"Minimum payments let interest erode the balance of the bill, so the debt grows month by month."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Sisa tagihan dikenakan bunga dan utang bertambah","options":["Sisa tagihan dikenakan bunga dan utang bertambah","Tagihan langsung lunas","Ia mendapat reward tambahan","Bank menghapuskan bunganya"],"question":"Apa yang terjadi jika Doni hanya membayar minimum tagihan kartu kreditnya?","difficulty":"beginner","explanation":"Pembayaran minimum membiarkan bunga menggerus sisa tagihan, sehingga utang tumbuh dari bulan ke bulan."}$json$::jsonb where id = '9bffdb6f-0cf7-429e-b11f-3c28621b960a';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"LPS guarantees all deposits in banks without limits.","difficulty":"beginner","explanation":"Wrong. LPS only guarantees deposits of up to IDR 2 billion per customer per bank. Above that, you do so at your own risk."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"LPS menjamin semua simpanan di bank tanpa batas.","difficulty":"beginner","explanation":"Salah. LPS hanya menjamin simpanan hingga Rp 2 miliar per nasabah per bank. Di atas itu, kamu menanggung risiko sendiri."}$json$::jsonb where id = '9fab58fb-66e4-4774-8840-a391bc5b5eb2';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"All PayLater services in Indonesia are illegal.","difficulty":"beginner","explanation":"Many PayLaters are licensed by the OJK, but users still have to be careful and only use registered services."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"Semua layanan PayLater di Indonesia ilegal.","difficulty":"beginner","explanation":"Banyak PayLater berizin OJK, tetapi pengguna tetap harus waspada dan hanya memakai layanan yang terdaftar."}$json$::jsonb where id = 'a22d2849-4c2b-4f26-9f7d-ff9c784227d9';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"OJK regulates crypto as a capital market product like shares and mutual funds.","difficulty":"beginner","explanation":"Crypto in Indonesia is regulated by CoFTRA as a commodity, not by the OJK as a capital market product."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"OJK mengatur kripto sebagai produk pasar modal seperti saham dan reksa dana.","difficulty":"beginner","explanation":"Kripto di Indonesia diatur oleh Bappebti sebagai komoditas, bukan oleh OJK sebagai produk pasar modal."}$json$::jsonb where id = 'a359b359-67e6-42b9-9a07-c7ba806281a0';
update public.content_variants set body = $json${"text":"Rina has an online business and needs an account for customer transactions. He opened a Giro account at Mandiri because he could receive large transfers and there was a checkbook for payments to suppliers. The Giro account does not earn high interest, but is flexible for business."}$json$::jsonb, body_id = $json${"text":"Rina punya bisnis online dan butuh rekening untuk transaksi pelanggan. Dia buka rekening Giro di Mandiri karena bisa terima transfer dalam jumlah besar dan ada buku cek untuk pembayaran ke supplier. Rekening Giro-nya tidak dapat bunga tinggi, tapi fleksibel untuk bisnis."}$json$::jsonb where id = 'a3d26a22-04a0-4b3c-a4b7-10a9c0c70fae';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Used for things that increase future income or wealth","options":["Used for things that increase future income or wealth","Has zero percent interest","Given by a friend without collateral","Used to buy branded goods"],"question":"What makes a debt called good debt?","difficulty":"beginner","explanation":"Good debt produces greater value in the future, for example education or a profitable business."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Digunakan untuk hal yang meningkatkan pendapatan atau kekayaan di masa depan","options":["Digunakan untuk hal yang meningkatkan pendapatan atau kekayaan di masa depan","Memiliki bunga nol persen","Diberikan oleh teman tanpa jaminan","Digunakan untuk membeli barang branded"],"question":"Apa yang membuat sebuah utang disebut utang baik?","difficulty":"beginner","explanation":"Utang baik menghasilkan nilai lebih besar di masa depan, misalnya pendidikan atau usaha yang menguntungkan."}$json$::jsonb where id = 'a68e2bef-dfef-4b73-91e6-93b360035886';
update public.content_variants set body = $json${"text":"Andi took KUR Rp. 10 million to buy a coffee cart. Every month he makes a profit of IDR 3 million and the installments are only IDR 800 thousand. For Andi, the loan is good debt because it generates income. His friend Eko took out Rp. 15 million in motorbike credit just to hang out at the weekend. Installments of Rp. 800 thousand per month only drain his money without additional income. That's bad debt."}$json$::jsonb, body_id = $json${"text":"Andi mengambil KUR Rp 10 juta untuk membeli gerobak kopi. Setiap bulan ia untung Rp 3 juta dan cicilan hanya Rp 800 ribu. Untuk Andi, pinjaman itu adalah utang baik karena menghasilkan pendapatan. Temannya Eko mengambil kredit motor Rp 15 juta hanya untuk nongkrong akhir pekan. Cicilan Rp 800 ribu per bulan hanya menguras uangnya tanpa penghasilan tambahan. Itu utang buruk."}$json$::jsonb where id = 'a7ae5ce1-93c7-46d6-84b7-ecb36e5a52f8';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"If the full bill is paid every month and used according to budget","options":["If the full bill is paid every month and used according to budget","If the limit is large","If you only pay the minimum","If used to buy branded goods"],"question":"When is a credit card considered good?","difficulty":"beginner","explanation":"Credit cards can be a financial tool if they are used disciplinedly and do not incur interest."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Jika tagihan penuh dibayar setiap bulan dan digunakan sesuai anggaran","options":["Jika tagihan penuh dibayar setiap bulan dan digunakan sesuai anggaran","Jika limitnya besar","Jika hanya membayar minimum","Jika digunakan untuk membeli barang branded"],"question":"Kapan kartu kredit disebut baik?","difficulty":"beginner","explanation":"Kartu kredit menjadi alat bantu keuangan jika digunakan dengan disiplin dan tidak menimbulkan bunga."}$json$::jsonb where id = 'a984bc23-246d-4442-b06c-7e29ed54976c';
update public.content_variants set body = $json${"type":"fill_blank","answer":"Certain","question":"If a coin promises _____ returns and forces you to recruit friends, it's probably a scam.","difficulty":"beginner","explanation":"Fixed returns and recruitment schemes are common features of crypto and pyramid scams."}$json$::jsonb, body_id = $json${"type":"fill_blank","answer":"pasti","question":"Jika sebuah koin menjanjikan imbal hasil _____ dan memaksamu merekrut teman, kemungkinan besar itu penipuan.","difficulty":"beginner","explanation":"Imbal hasil pasti dan skema rekrutmen adalah ciri umum penipuan kripto dan piramida."}$json$::jsonb where id = 'ad44d8c7-6131-4c01-a7fc-a104b8b09a28';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Coin developers disappear along with investors' money","options":["Coin developers disappear along with investors' money","Crypto prices rise 100%","Central banks withdraw crypto from the market","The process of selling crypto legally"],"question":"What is meant by rug pull?","difficulty":"beginner","explanation":"A rug pull occurs when a coin maker runs away after collecting a lot of people's money, leaving coins with no value."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Pengembang koin menghilang bersama uang investor","options":["Pengembang koin menghilang bersama uang investor","Harga kripto naik 100%","Bank sentral menarik kripto dari pasar","Proses menjual kripto secara legal"],"question":"Apa yang dimaksud dengan rug pull?","difficulty":"beginner","explanation":"Rug pull terjadi ketika pembuat koin kabur setelah mengumpulkan uang banyak orang, meninggalkan koin tanpa nilai."}$json$::jsonb where id = 'aec394d0-e103-40cf-8317-f8cc272d6984';

